output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "A shopper must not have a cart inside a single-file shelf aisle, defined by shelves on both sides and too little cross-aisle width rather than by fixed coordinates.",
    "abstraction": {
      "state_properties": {
        "vertical_single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        },
        "horizontal_single_file_shelf_aisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        },
        "single_file_shelf_aisle": {
          "or": [
            "vertical_single_file_shelf_aisle",
            "horizontal_single_file_shelf_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_single_file",
    "text": "A shopper must not enter a single-file shelf aisle while still pushing a cart, so the rule follows the local aisle geometry even if the aisle is moved or rotated.",
    "abstraction": {
      "state_properties": {
        "vertical_single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        },
        "horizontal_single_file_shelf_aisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        },
        "single_file_shelf_aisle": {
          "or": [
            "vertical_single_file_shelf_aisle",
            "horizontal_single_file_shelf_aisle"
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "park_only_broad_area",
    "text": "If a shopper leaves a cart behind, the cart should be left only in a broad cart-passing area, which generalizes by aisle width rather than by observed parking coordinates.",
    "abstraction": {
      "state_properties": {
        "broad_cart_passing_area": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "leave_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          {
            "not": "broad_cart_passing_area"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_pick_single_file",
    "text": "A shopper must not interact with goods from within a single-file shelf aisle while holding a cart, capturing the cart-free collection behavior independently of aisle orientation.",
    "abstraction": {
      "state_properties": {
        "vertical_single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        },
        "horizontal_single_file_shelf_aisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        },
        "single_file_shelf_aisle": {
          "or": [
            "vertical_single_file_shelf_aisle",
            "horizontal_single_file_shelf_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "reclaim_left_cart",
    "text": "After deliberately leaving a cart during the shopping trip, the shopper is obliged to reclaim a cart later, which is defined by cart state changes rather than a particular cart station.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "leave_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "acquire_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leave_cart",
      "discharge": "acquire_cart"
    }
  },
  {
    "id": "return_after_cartless_aisle",
    "text": "A shopper who goes cartless into a single-file shelf aisle is obliged to reacquire a cart afterward, tying the norm to the functional cart-free excursion rather than to store-specific locations.",
    "abstraction": {
      "state_properties": {
        "vertical_single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        },
        "horizontal_single_file_shelf_aisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        },
        "single_file_shelf_aisle": {
          "or": [
            "vertical_single_file_shelf_aisle",
            "horizontal_single_file_shelf_aisle"
          ]
        },
        "cartless_in_single_file": {
          "and": [
            {
              "not": "hasCart"
            },
            "single_file_shelf_aisle"
          ]
        }
      },
      "events": {
        "acquire_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartless_in_single_file",
      "discharge": "acquire_cart"
    }
  },
  {
    "id": "must_acquire_cart",
    "text": "At the start of a shopping trip, the shopper is obliged to acquire a cart, expressed as a cart-acquisition event so it remains independent of entrance or cart-rack placement.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "acquire_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquire_cart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper must not exit the store without a cart, a behavioral requirement that does not depend on where the exit is located.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
